            { const [A, B] = await fresh(); const m = put(A, 'Esior, Wardwing Familiar'); m.isCommander = true; const sp = makeObj(have('Shock'), 1); sp._tgt = { o: m }; const t3 = costTotal(costOf(B, sp)); sp._tgt = null; ok('Esior: spells that target a commander you control cost 3 more', t3 === costTotal(Rx(sp).cost) + 3 && costTotal(costOf(B, sp)) === costTotal(Rx(sp).cost), [t3]); }
            { const [A] = await fresh(); const an = put(A, 'Animar, Soul of Elements'); an.counters = 2; const c = makeObj(have('Hill Giant'), 0); ok('Animar: creature spells cost 1 less for each +1/+1 counter on it', costTotal(costOf(A, c)) === costTotal(Rx(c).cost) - 2, costTotal(costOf(A, c))); }
